import type { ReceiptChargeLine, ReceiptChargeType } from "@/lib/types";

/** Bag / poşet / bez çanta charges — never products. */
const BAG_PATTERN =
  /\b(po[sş]et(\s*(ücreti|ucreti|bedeli))?|alışveriş\s*po[sş]eti|alisveris\s*poseti|market\s*po[sş]eti|market\s*poseti|bez\s*çanta|bez\s*canta|shopping\s*bag|bag\s*fee)\b/i;

/** Shipping / delivery / kargo charges. */
const SHIPPING_PATTERN =
  /\b(kargo(\s*(bedeli|ücreti|ucreti))?|teslimat(\s*(bedeli|ücreti|ucreti))?|delivery|shipping|nakliye|getirme\s*(ücreti|ucreti))\b/i;

/** Service / platform fees. */
const SERVICE_PATTERN =
  /\b(hizmet\s*(bedeli|ücreti|ucreti)|servis\s*(bedeli|ücreti|ucreti)|service\s*fee|platform\s*(ücreti|ucreti)|işlem\s*(ücreti|ucreti)|islem\s*(ucreti|ucreti)|komisyon)\b/i;

/** Packaging / ambalaj fees. */
const PACKAGING_PATTERN =
  /\b(paketleme|packaging|ambalaj(\s*(ücreti|ucreti|bedeli))?)\b/i;

/** Standalone charge labels (common OCR abbreviations). */
const STANDALONE_CHARGE =
  /^(po[sş]et|poset|kargo|teslimat|delivery|shipping|bez\s*çanta|bez\s*canta|servis|hizmet)$/i;

/** Labels that are receipt-level discounts, not products. */
export const DISCOUNT_LABEL =
  /\b(indirim|iskonto|discount|kupon|coupon|kampanya|promo(tion)?|puan\s*indirim|loyalty\s*discount)\b/i;

/**
 * Classify a receipt-level charge line by label text.
 * Returns null when the name is not a known charge type.
 */
export function classifyReceiptCharge(name: string): ReceiptChargeType | null {
  const t = name.trim();
  if (!t) return null;

  if (BAG_PATTERN.test(t)) return "bag";
  if (SHIPPING_PATTERN.test(t)) return "shipping";
  if (SERVICE_PATTERN.test(t)) return "service";
  if (PACKAGING_PATTERN.test(t)) return "packaging";

  if (STANDALONE_CHARGE.test(t)) {
    if (/po[sş]et|bez/i.test(t)) return "bag";
    if (/kargo|teslimat|delivery|shipping/i.test(t)) return "shipping";
    if (/servis|hizmet/i.test(t)) return "service";
  }

  return null;
}

export function isReceiptChargeLine(name: string): boolean {
  return classifyReceiptCharge(name) != null;
}

export function isReceiptDiscountLine(name: string): boolean {
  return DISCOUNT_LABEL.test(name.trim());
}

export function toReceiptChargeLine(
  name: string,
  amount: number
): ReceiptChargeLine {
  return {
    type: classifyReceiptCharge(name) ?? "other",
    label: name.trim(),
    amount: Math.abs(amount),
  };
}

/** Ensure every charge line has a type (backward compat for stored data). */
export function normalizeChargeLine(
  line: Partial<ReceiptChargeLine> & { label?: string; amount: number }
): ReceiptChargeLine {
  const raw = line as { label?: string; description?: string };
  const label =
    raw.label?.trim() ||
    (typeof raw.description === "string" ? raw.description.trim() : "");
  const type =
    line.type && line.type !== "other"
      ? line.type
      : classifyReceiptCharge(label) ?? "other";
  return {
    type,
    label,
    amount: Math.abs(line.amount),
  };
}
